/* C API of the Rust port of `mathematics.c`, generated by everything-rust. */
#ifndef MATHEMATICS_RS_H
#define MATHEMATICS_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

typedef struct { int num; int den; } AVRational;

int64_t av_gcd(int64_t a, int64_t b);
int64_t av_rescale_rnd(int64_t a, int64_t b, int64_t c, int rnd);
int64_t av_rescale(int64_t a, int64_t b, int64_t c);
int64_t av_rescale_q_rnd(int64_t a, AVRational bq, AVRational cq, int rnd);
int64_t av_rescale_q(int64_t a, AVRational bq, AVRational cq);
int64_t av_compare_mod(uint64_t a, uint64_t b, uint64_t mod);
double av_bessel_i0(double x);

/* The same functions under `everything_rust_` names, for shadow runs. */
int64_t everything_rust_av_gcd(int64_t a, int64_t b);
int64_t everything_rust_av_rescale_rnd(int64_t a, int64_t b, int64_t c, int rnd);
int64_t everything_rust_av_rescale(int64_t a, int64_t b, int64_t c);
int64_t everything_rust_av_rescale_q_rnd(int64_t a, AVRational bq, AVRational cq, int rnd);
int64_t everything_rust_av_rescale_q(int64_t a, AVRational bq, AVRational cq);
int64_t everything_rust_av_compare_mod(uint64_t a, uint64_t b, uint64_t mod);
double everything_rust_av_bessel_i0(double x);

#endif /* MATHEMATICS_RS_H */
